using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";

        if (!File.Exists(dataPath)) {
            CPH.SendMessage($"@{userName}, no PvP challenges found.");
            return false;
        }

        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Check for pending challenge
        if (data["pvpChallenges"] == null || data["pvpChallenges"][userId] == null) {
            CPH.SendMessage($"@{userName}, you don't have any pending PvP challenges.");
            return false;
        }

        JToken challenge = data["pvpChallenges"][userId];
        string challengerId = challenge["challengerId"].ToString();
        string challengerName = challenge["challengerName"].ToString();
        int wager = (int)challenge["wager"];
        DateTime timestamp = DateTime.Parse(challenge["timestamp"].ToString());

        // Check if challenge has expired (60 seconds)
        if ((DateTime.UtcNow - timestamp).TotalSeconds > 60) {
            data["pvpChallenges"][userId] = null;
            File.WriteAllText(dataPath, data.ToString());
            CPH.SendMessage($"@{userName}, the PvP challenge from @{challengerName} has expired.");
            return false;
        }

        // Verify both players still have tokens
        int challengerTokens = (int)(data["users"][challengerId]["rrTokens"] ?? 0);
        int defenderTokens = (int)(data["users"][userId]["rrTokens"] ?? 0);

        if (challengerTokens < wager) {
            CPH.SendMessage($"@{userName}, @{challengerName} no longer has enough tokens for this battle.");
            data["pvpChallenges"][userId] = null;
            File.WriteAllText(dataPath, data.ToString());
            return false;
        }

        if (defenderTokens < wager) {
            CPH.SendMessage($"@{userName}, you don't have enough RRTokens for this battle! You need {wager}.");
            return false;
        }

        // BATTLE TIME!
        Random rnd = new Random();

        // Initiative rolls
        int challengerInit = rnd.Next(1, 21);
        int defenderInit = rnd.Next(1, 21);

        string firstAttacker = challengerId;
        string firstAttackerName = challengerName;
        string secondAttacker = userId;
        string secondAttackerName = userName;

        if (defenderInit > challengerInit) {
            firstAttacker = userId;
            firstAttackerName = userName;
            secondAttacker = challengerId;
            secondAttackerName = challengerName;
        }

        // 3 rounds of combat
        int challengerWins = 0;
        int defenderWins = 0;
        string[] weapons = {"sword", "axe", "hammer", "dagger", "spear", "mace"};
        string[] actions = {"swings", "strikes", "slashes", "thrusts", "charges with"};
        string[] defenses = {"dodges", "parries", "blocks", "deflects"};

        string battleLog = $"⚔️ PvP Battle: @{challengerName} vs @{userName} ({wager} RRTokens wagered)\n";
        battleLog += $"🎲 Initiative! {challengerName}: {challengerInit}, {userName}: {defenderInit}\n";
        battleLog += $"@{firstAttackerName} strikes first!\n\n";

        for (int round = 1; round <= 3; round++) {
            int attackRoll = rnd.Next(1, 21);
            int defenseRoll = rnd.Next(1, 21);
            int damage = rnd.Next(5, 13);

            string weapon = weapons[rnd.Next(weapons.Length)];
            string action = actions[rnd.Next(actions.Length)];
            string defense = defenses[rnd.Next(defenses.Length)];

            string attacker = (round % 2 == 1) ? firstAttackerName : secondAttackerName;
            string defender = (round % 2 == 1) ? secondAttackerName : firstAttackerName;

            battleLog += $"Round {round}:\n";
            battleLog += $"@{attacker} {action} their {weapon}! (Rolled {attackRoll})\n";
            battleLog += $"@{defender} {defense}! (Rolled {defenseRoll})\n";

            if (attackRoll > defenseRoll) {
                battleLog += $"💥 Hit! {damage} damage!\n";
                if (attacker == challengerName) challengerWins++;
                else defenderWins++;
            } else {
                battleLog += $"Miss!\n";
            }

            if (round < 3) battleLog += "\n";
        }

        // Determine winner
        string winner, loser;
        string winnerId, loserId;

        if (challengerWins > defenderWins) {
            winner = challengerName;
            winnerId = challengerId;
            loser = userName;
            loserId = userId;
        } else if (defenderWins > challengerWins) {
            winner = userName;
            winnerId = userId;
            loser = challengerName;
            loserId = challengerId;
        } else {
            // Draw
            battleLog += $"\n⚔️ It's a DRAW! Both fighters are evenly matched!\n";
            battleLog += $"Both players keep their tokens and receive 25 consolation eggs each!";

            int challengerEggs = (int)(data["users"][challengerId]["eggs"] ?? 0);
            int defenderEggs = (int)(data["users"][userId]["eggs"] ?? 0);
            data["users"][challengerId]["eggs"] = challengerEggs + 25;
            data["users"][userId]["eggs"] = defenderEggs + 25;

            data["pvpChallenges"][userId] = null;
            File.WriteAllText(dataPath, data.ToString());

            CPH.SendMessage(battleLog);
            return true;
        }

        battleLog += $"\n⚔️ @{winner} WINS! 🏆\n";
        battleLog += $"@{winner} gains {wager} RRTokens + 50 bonus eggs!\n";
        battleLog += $"@{loser} receives 10 consolation eggs.";

        // Update tokens and eggs
        int winnerTokens = (int)(data["users"][winnerId]["rrTokens"] ?? 0);
        int loserTokens = (int)(data["users"][loserId]["rrTokens"] ?? 0);
        int winnerEggs = (int)(data["users"][winnerId]["eggs"] ?? 0);
        int loserEggs = (int)(data["users"][loserId]["eggs"] ?? 0);

        data["users"][winnerId]["rrTokens"] = winnerTokens + wager;
        data["users"][loserId]["rrTokens"] = loserTokens - wager;
        data["users"][winnerId]["eggs"] = winnerEggs + 50;
        data["users"][loserId]["eggs"] = loserEggs + 10;

        // Remove challenge
        data["pvpChallenges"][userId] = null;

        File.WriteAllText(dataPath, data.ToString());

        CPH.SendMessage(battleLog);

        return true;
    }
}
